import { useState, Fragment } from "react";
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Typography from "@mui/material/Typography";
import Grid from "@mui/material/Grid";

// Icons
import IconButton from "@mui/material/IconButton";
import CheckIcon from "@mui/icons-material/Check";
import CreateIcon from "@mui/icons-material/Create";
import DeleteIcon from "@mui/icons-material/Delete";

// Import Context
import { useContext } from "react";
import { TodoContext } from "../context/TodoContext";

// Dialog Imports
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogContentText from "@mui/material/DialogContentText";
import DialogTitle from "@mui/material/DialogTitle";
import TextField from "@mui/material/TextField";

// Import SnackBar
import { useSnackbar } from "../context/SnackbarContext";

export default function Todo({ todo }) {
  const { todos, setTodos } = useContext(TodoContext);
  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [updatedTodo, setUpdatedTodo] = useState({
    title: todo.title,
    details: todo.description,
  });

  const handleOpenDeleteDialog = () => {
    setOpenDeleteDialog(true);
  };

  const handleCloseDeleteDialog = () => {
    setOpenDeleteDialog(false);
  };
  const handleOpenEditDialog = () => {
    setOpenEditDialog(true);
  };

  const handleCloseEditDialog = () => {
    setOpenEditDialog(false);
  };

  // Use SnackBar
  const { showSnackbar } = useSnackbar();
  return (
    <>
      {/* Start Delete dialog   */}
      <Fragment>
        <Dialog
          open={openDeleteDialog}
          onClose={handleCloseDeleteDialog}
          aria-labelledby="alert-dialog-title"
          aria-describedby="alert-dialog-description"
          role="alertdialog"
          style={{ direction: "rtl" }}
        >
          <DialogTitle id="alert-dialog-title">
            {"هل أنت متأكد من رغبتك في خذف المهمه؟"}
          </DialogTitle>
          <DialogContent>
            <DialogContentText id="alert-dialog-description">
              لا يمكنك الترجع عن الحذف في حال إختيار زر
            </DialogContentText>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => {
                handleCloseDeleteDialog();
              }}
            >
              إغلاق
            </Button>
            <Button
              onClick={() => {
                const deletedTodo = todos.filter((item) => item.id !== todo.id);

                setTodos(deletedTodo);
                localStorage.setItem("todos", JSON.stringify(deletedTodo));

                handleCloseDeleteDialog();
                showSnackbar("تم حذف المهمة بنجاح", "error");
              }}
            >
              نعم قم بالحذف
            </Button>
          </DialogActions>
        </Dialog>
      </Fragment>
      {/* End Delete Dialog   */}

      {/* Start Edit Dialog   */}
      <Fragment>
        <Dialog
          open={openEditDialog}
          onClose={handleOpenEditDialog}
          aria-labelledby="alert-dialog-title"
          aria-describedby="alert-dialog-description"
          role="alertdialog"
          style={{ direction: "rtl" }}
        >
          <DialogTitle id="alert-dialog-title">{"تعديل المهمه"}</DialogTitle>
          <DialogContent>
            <TextField
              margin="dense"
              id="title"
              name="title"
              label="العنوان"
              fullWidth
              variant="standard"
              value={updatedTodo.title}
              onChange={(event) => {
                setUpdatedTodo({ ...updatedTodo, title: event.target.value });
              }}
            />
            <TextField
              margin="dense"
              id="details"
              name="details"
              label="التفاصيل"
              fullWidth
              variant="standard"
              value={updatedTodo.details}
              onChange={(event) => {
                setUpdatedTodo({ ...updatedTodo, details: event.target.value });
              }}
            />
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => {
                handleCloseEditDialog();
              }}
            >
              إلغاء
            </Button>
            <Button
              disabled={!updatedTodo.title}
              onClick={() => {
                const updatedTodos = todos.map((t) => {
                  if (t.id === todo.id) {
                    return {
                      ...t,
                      title: updatedTodo.title,
                      description: updatedTodo.details,
                    };
                  } else return t;
                });

                setTodos(updatedTodos);
                localStorage.setItem("todos", JSON.stringify(updatedTodos));
                handleCloseEditDialog();
                showSnackbar("تم تعديل المهمة بنجاح", "info");
              }}
            >
              تعديل
            </Button>
          </DialogActions>
        </Dialog>
      </Fragment>
      {/* End Edit dialog   */}
      <Card
        sx={{
          minWidth: 275,
          backgroundColor: "#283593",
          color: "white",
          marginTop: 5,
        }}
        className="todo-card"
      >
        <CardContent>
          <Grid
            container
            spacing={1}
            sx={{
              display: "flex",
              alignItems: "center",
            }}
          >
            {/* Task title */}
            <Grid size={8}>
              <Typography
                variant="h5"
                sx={{
                  textAlign: "right",
                  textDecoration: todo.isCompleted ? "line-through" : "none",
                }}
              >
                {todo.title}
              </Typography>
              <Typography variant="h6" sx={{ textAlign: "right" }}>
                {todo.description}
              </Typography>
            </Grid>

            {/* Start Action Buttons */}
            <Grid
              size={4}
              container
              wrap="nowrap"
              sx={{ justifyContent: "center" }}
            >
              {/* START CHICK ICON BOTTON  */}
              <IconButton
                className={`action-buttons ${todo.isCompleted ? "active" : ""}`}
                aria-label="complete"
                size="medium"
                onClick={() => {
                  const updatedTodos = todos.map((t) => {
                    if (t.id === todo.id) {
                      t.isCompleted = !t.isCompleted;
                    }

                    return t;
                  });
                  setTodos(updatedTodos);
                  localStorage.setItem("todos", JSON.stringify(updatedTodos));
                  showSnackbar(
                    updatedTodos.find((t) => t.id === todo.id).isCompleted
                      ? "تم إنجاز المهمة"
                      : "تم إرجاع المهمة إلى غير منجزة",
                    "success",
                  );
                }}
              >
                <CheckIcon />
              </IconButton>
              {/* END CHICK ICON BOTTON  */}
              {/* START EDIT ICON BOTTON  */}
              <IconButton
                className="action-buttons"
                aria-label="edit"
                size="medium"
                onClick={() => {
                  handleOpenEditDialog();
                }}
              >
                <CreateIcon />
              </IconButton>
              {/* END EDIT ICON BOTTON  */}
              {/* START DELETE ICON BOTTON  */}
              <IconButton
                className="action-buttons"
                aria-label="delete"
                size="medium"
                onClick={() => {
                  handleOpenDeleteDialog();
                }}
              >
                <DeleteIcon />
              </IconButton>

              {/* END DELETE ICON BOTTON  */}
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </>
  );
}
