import Stack from "@mui/material/Stack";
import Button from "@mui/material/Button";
import Container from "@mui/material/Container";
import ToggleButton from "@mui/material/ToggleButton";
import ToggleButtonGroup from "@mui/material/ToggleButtonGroup";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import { useState, useContext, useEffect } from "react";
import { useSnackbar } from "../context/SnackbarContext";

// Import Alert Tools
import Snackbar, { SnackbarCloseReason } from "@mui/material/Snackbar";
import Alert from "@mui/material/Alert";

// uuidv4
import { v4 as uuidv4 } from "uuid";

// Use Context
import { TodoContext } from "../context/TodoContext.js";

// Componets
import Todo from "./Todo";

export default function TodoList() {
  const [titleInput, setTitleInput] = useState("");
  const { todos, setTodos } = useContext(TodoContext);

  // Displayed Todos Type
  const [displayedTodosType, setDisplayedTodosType] = useState("all");

  const isCompletedTodosList = todos.filter((todo) => {
    return todo.isCompleted;
  });
  const isNotCompletedTodosList = todos.filter((todo) => {
    return !todo.isCompleted;
  });

  let todosToBeRendered = todos;

  if (displayedTodosType === "completed") {
    todosToBeRendered = isCompletedTodosList;
  } else if (displayedTodosType === "non-completed") {
    todosToBeRendered = isNotCompletedTodosList;
  } else {
    todosToBeRendered = todos;
  }

  const todosJsx = todosToBeRendered.map((todo) => {
    return <Todo key={todo.id} todo={todo} />;
  });

  // Get the todos from Local Storage
  useEffect(() => {
    setTodos(JSON.parse(localStorage.getItem("todos")) || []);
  }, []);

  function handleAddNewTask() {
    const newTodo = {
      id: uuidv4(),
      title: titleInput,
      description: "",
      isCompleted: false,
    };

    const updatedTodos = [...todos, newTodo];
    setTodos(updatedTodos);
    localStorage.setItem("todos", JSON.stringify(updatedTodos));
    setTitleInput("");
  }

  const [openAlert, setOpenAlert] = useState(false);

  const handleAddTodosSnackBar = () => {
    setOpenAlert(true);
  };

  const handleClose = () => {
    setOpenAlert(false);
  };

  const { showSnackbar } = useSnackbar();

  return (
    <Container
      maxWidth="sm"
      style={{
        backgroundColor: "white",
        padding: "20px",
        maxHeight: "80vh",
        overflowY: "scroll",
      }}
    >
      <Typography variant="h1">مهامي</Typography>
      {/* Start Filter Bottons Section  */}
      <ToggleButtonGroup
        value={displayedTodosType}
        exclusive
        color="primary"
        onChange={(e) => {
          setDisplayedTodosType(e.target.value);
        }}
        style={{ direction: "ltr", marginTop: "15px" }}
      >
        <ToggleButton value="non-completed">غير منجز</ToggleButton>
        <ToggleButton value="completed">منجز</ToggleButton>
        <ToggleButton value="all">الكل</ToggleButton>
      </ToggleButtonGroup>
      {/* Start Filter Bottons Section  */}
      {/* Start todo List Section  */}
      {todosJsx}
      {/* End todo List Section  */}
      {/* Start Footer Section  */}
      <Stack direction="row" spacing={1} style={{ marginTop: "50px" }}>
        <TextField
          id="outlined-basic"
          label="عنوان المهمه"
          variant="outlined"
          style={{ flex: "1" }}
          size="small"
          onChange={(e) => {
            setTitleInput(e.target.value);
          }}
          value={titleInput}
        />
        <Button
          disabled={!titleInput}
          variant="contained"
          style={{ width: "100px", marginRight: "7px" }}
          onClick={() => {
            handleAddNewTask();
            showSnackbar("تمت إضافة المهمة بنجاح", "success");
          }}
        >
          إضافه
        </Button>
        <Snackbar
          open={openAlert}
          autoHideDuration={2000}
          onClose={handleClose}
        >
          <Alert
            onClose={handleClose}
            severity="success"
            variant="filled"
            sx={{ width: "100%" }}
          >
            {" "}
            <div style={{ padding: "0 8px" }}>تم إضافه المهمه بنجاح</div>
          </Alert>
        </Snackbar>
      </Stack>
      {/* End Footer Section  */}
    </Container>
  );
}
